    assert True and True
except Exception as e:
    print(f"{type(e).__name__}:{e}")

try:
    assert True and False
except Exception as e:
    print(f"{type(e).__name__}:{e}")

try:
    assert True and ~0j
except Exception as e:
    print(f"{type(e).__name__}:{e}")

try:
    assert False and True
except Exception as e:
    print(f"{type(e).__name__}:{e}")

try:
    assert False and False
except Exception as e:
    print(f"{type(e).__name__}:{e}")

try:
    assert False and ~0j
except Exception as e:
    print(f"{type(e).__name__}:{e}")

try:
    assert ~0j and True
except Exception as e:
    print(f"{type(e).__name__}:{e}")

try:
    assert ~0j and False
except Exception as e:
    print(f"{type(e).__name__}:{e}")

try:
    assert ~0j and ~0j
except Exception as e:
    print(f"{type(e).__name__}:{e}")

try:
