try:
    assert not (True or ~0j)
except Exception as e:
    print(f"{type(e).__name__}:{e}")

try:
    assert not (False or True)
except Exception as e:
    print(f"{type(e).__name__}:{e}")

try:
    assert not (False or False)
except Exception as e:
    print(f"{type(e).__name__}:{e}")

try:
    assert not (False or ~0j)
