assert (
    # ...
    True and True
)
assert True and True  # ...
# EOF

$ ruff --isolated check pt018_2.py --select PT018 --unsafe-fixes --fix --output-format concise
pt018_2.py:1:1: PT018 Assertion should be broken down into multiple parts
